package no.eskmag.bronnplan.core.model;

import java.util.Arrays;

import no.eskmag.bronnplan.core.units.Units;

/**
 * How the annual heat demand is distributed over the twelve months of a year.
 * Index 0 is January, index 11 is December. See docs/model.md §3.2.
 *
 * @param fractions share of the annual demand per month [–], each &ge; 0, summing to 1 (tolerance 1e-6)
 */
public record MonthlyProfile(double[] fractions) {

    static final double SUM_TOLERANCE = 1e-6;

    /**
     * Heating degree days, base 17 °C, from monthly normals 1991–2020 for Bergen (Florida).
     * Generated by tools/validation/generate_references.py. The normals are not yet verified
     * against seKlima (docs/model.md §3.2).
     */
    private static final double[] BERGEN_DEGREE_DAYS = {
            0.139534884, 0.127781945, 0.127906977, 0.096586647, 0.066860465, 0.037509377,
            0.016472868, 0.018410853, 0.044073518, 0.081395349, 0.108777194, 0.134689922,
    };

    public MonthlyProfile {
        if (fractions == null || fractions.length != Units.MONTHS_PER_YEAR) {
            throw new IllegalArgumentException("fractions [–] must have " + Units.MONTHS_PER_YEAR + " values, got "
                    + (fractions == null ? "null" : fractions.length));
        }
        fractions = fractions.clone();
        double sum = 0.0;
        for (int m = 0; m < fractions.length; m++) {
            if (!(fractions[m] >= 0.0) || Double.isInfinite(fractions[m])) {
                throw new IllegalArgumentException(
                        "fractions[" + m + "] [–] must be non-negative and finite, got " + fractions[m]);
            }
            sum += fractions[m];
        }
        if (Math.abs(sum - 1.0) > SUM_TOLERANCE) {
            throw new IllegalArgumentException("fractions [–] must sum to 1, got " + sum);
        }
    }

    public static MonthlyProfile bergenDegreeDays() {
        return new MonthlyProfile(BERGEN_DEGREE_DAYS);
    }

    /** Defensive copy, so the profile cannot be changed after validation. */
    @Override
    public double[] fractions() {
        return fractions.clone();
    }

    /** @param month 0 = January … 11 = December */
    public double fraction(int month) {
        return fractions[month];
    }

    /** Month with the largest share of the demand; the first one on ties. 0 = January. */
    public int coldestMonth() {
        int coldest = 0;
        for (int m = 1; m < fractions.length; m++) {
            if (fractions[m] > fractions[coldest]) {
                coldest = m;
            }
        }
        return coldest;
    }

    // Records compare array components by reference; compare contents instead.
    @Override
    public boolean equals(Object o) {
        return o instanceof MonthlyProfile other && Arrays.equals(fractions, other.fractions);
    }

    @Override
    public int hashCode() {
        return Arrays.hashCode(fractions);
    }

    @Override
    public String toString() {
        return "MonthlyProfile" + Arrays.toString(fractions);
    }
}
